const health = $input.first().json;
const failures = health?.integration?.recentFailures || [];
const dead = health?.integration?.deadLetterDeliveries || 0;
const msg = dead > 0 || failures.length
  ? `ASF n8n delivery issues: dead_letter=${dead}, recent_failures=${failures.length}. Retry from ASF Automation UI. Do NOT auto-submit Flow.`
  : 'ASF n8n integration healthy';
return [{ json: { actionable: dead > 0 || failures.length > 0, message: msg, health } }];
